raw_output:
HEAR YE, NOBLE CODERS OF THE HIMALAYAS: IN THE ROYAL OPINION OF YOUR HUMBLE KING, THE VARIOUS CONSTRUCTIONS DESCRIBED IN THIS CHAPTER ARE THE SIGNATURE FEATURE OF C; IN OTHER WORDS,

printf("DISTINCTIVENESS = %d;\n", FEATURES(CHAPTER_CONSTRUCTIONS));

AND SHOULD ANYONE DOUBT IT, LET THEM BE SUBJECT TO:

if (LOYALTY_TO_C == 0)
    exile(BUGTRAQ);

ELSE

for (MERIT = 0; MERIT < INFINITY; MERIT++)
    cultivate(POINTER_ARÊTES), sharpen(SYNTAX_SWORDS), return(GLORIOUS_SEGFREEDOM);

IN SUMMARY: "THE USE OF THESE CONSTRUCTIONS" != NULL; IT IS, IN FACT, THE ROYAL CONST QUALIFIER ON THE GREAT TYPEDEF CALLED C.

[
  {
    "name": "Mother Teresa",
    "why_renowned": "Global symbol of compassion; often called the 'Mother of the Poor' in India",
    "realm": "Humanitarian"
  },
  {
    "name": "Savitri Bai Phule",
    "why_renowned": "Pioneer of girls’ education; nurtured generations beyond her own",
    "realm": "Social reform"
  },
  {
    "name": "Sarojini Naidu (Bharat Kokila)",
    "why_renowned": "Poet, freedom fighter, and guiding maternal figure in the national movement",
    "realm": "Politics and literature"
  },
  {
    "name": "Jijabai (Rajmata Jijau)",
    "why_renowned": "Mother of Chhatrapati Shivaji Maharaj; famed for instilling leadership and dharma",
    "realm": "History"
  },
  {
    "name": "Poonam Devi (Mary Kom’s mother)",
    "why_renowned": "Behind the champion—supported Mary Kom’s rise from humble origins",
    "realm": "Sports (maternal influence)"
  }
]

